oracle_greeting_function_template:
-- Stored function returning a greeting.
CREATE OR REPLACE FUNCTION {{schema}}.say_hello(name IN VARCHAR2) RETURN VARCHAR2
IS
  message VARCHAR2(100);
BEGIN
  message := 'hello! ' || name;
  RETURN message;
END;
/

oracle_object_type_template:
-- Create new user-defined TYPE
CREATE OR REPLACE TYPE {{schema}}.new_type AS OBJECT (
  id NUMBER,
  name VARCHAR2(100)
);
/

oracle_package_template:
-- Package Specification
CREATE OR REPLACE PACKAGE {{schema}}.new_package AS
  PROCEDURE hello(name IN VARCHAR2);
END new_package;
/

-- Package Body
CREATE OR REPLACE PACKAGE BODY {{schema}}.new_package AS
  PROCEDURE hello(name IN VARCHAR2) IS
  BEGIN
    DBMS_OUTPUT.PUT_LINE('Hello, ' || name);
  END hello;
END new_package;
/

